'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = s => s ? new Date(s).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : '—';
const badge = s => `<span class="badge ${esc(String(s).replaceAll(' ','-'))}">${esc(String(s).replaceAll('_',' '))}</span>`;
const kinds = ['phone','email','person','username','domain','ip','image','instagram','facebook','linkedin','linkedin_company','tiktok','twitter','threads','bluesky','youtube','truthsocial','snapchat','pinterest','linktree','komi','pillar','linkbio','amazon_shop','github','website','organization','location','wallet','google_id'];
const options = (items,selected) => items.map(i=>`<option value="${esc(i)}" ${i===selected?'selected':''}>${esc(({person:'Name / person',ip:'IP address',linkedin_company:'LinkedIn company',amazon_shop:'Amazon shop'})[i]||i)}</option>`).join('');
let state={}, caseId=Number(new URLSearchParams(location.search).get('case'))||null, tab='Graph', selected=null, query='', typeFilter='', positions={}, view={x:0,y:0,k:1};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500)}
async function api(action,fields={}){
  const response=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json','X-Atlas-Token':state.csrf},body:JSON.stringify({action,case_id:caseId,...fields})});
  const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result;
}
async function refresh(){const response=await fetch('/api/state'+(caseId?'?case='+caseId:''));const result=await response.json();if(!response.ok)throw Error(result.error);state=result;render()}
async function act(action,fields={},message='Saved'){const result=await api(action,fields);await refresh();toast(message);return result}
function modal(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialog').showModal()}
function close(){ $('#dialog').close() }
function seedForm(){return `<div class="row"><div><label class="field" for="seedType">Starting entity</label><select id="seedType" class="full">${options(kinds,'domain')}</select></div><div><label class="field" for="seedValue">Identifier</label><input id="seedValue" class="full" placeholder="example.com"></div></div>`}
function newCase(){modal('Start an investigation',`<p class="muted">Give the case a name and add a starting identifier. You can add more seeds later.</p><label class="field" for="newTitle">Case name</label><input id="newTitle" class="full" placeholder="e.g. Organization background review" required><label class="field" for="newDescription">Purpose / scope</label><textarea id="newDescription" class="full" rows="2" placeholder="What are you trying to establish?"></textarea>${seedForm()}<div class="dialog-actions"><button class="primary" data-do="create-case">Create case</button></div>`)}
function navigate(id){caseId=Number(id);selected=null;positions={};view={x:0,y:0,k:1};query='';typeFilter='';tab='Graph';history.replaceState(null,'','?case='+caseId);return refresh()}
function render(){
 $('#cases').innerHTML=(state.cases||[]).map(c=>`<button class="case-link ${c.id===caseId?'active':''}" data-case="${c.id}" title="${esc(c.title)}">${esc(c.title)}</button>`).join('')||'<p class="note">No cases yet</p>';
 const c=state.case;
 $('#caseTitle').textContent=c?c.title:'Follow the evidence.';
 $('#caseDescription').textContent=c?c.description:'Bring sources together. Review the connections. Keep the trail.';
 $('#eyebrow').textContent=c?(c.demo?'FICTIONAL DEMONSTRATION':'CASE '+String(c.id).padStart(4,'0')):'YOUR INVESTIGATION DESK';
 $('#breadcrumb').innerHTML='WORKSPACE <span>/</span> '+(c?'INVESTIGATION':'OVERVIEW');
 $('#runButton').hidden=!c;
 const ready=(state.sources||[]).filter(s=>s.available).length;
 const metrics=c?[[state.nodes.length,'Entities','◇'],[state.edges.length,'Connections','⌁'],[state.evidence.length,'Evidence items','▤'],[state.evidence.filter(e=>e.review==='unreviewed').length,'Awaiting review','◷']]:[[state.cases.length,'Cases','◇'],[ready,'Connected sources','⌁'],[(state.sources||[]).filter(s=>s.implemented).length,'Built connectors','▤'],[73,'Captured transform IDs','◷']];
 $('#metrics').innerHTML=metrics.map(([n,l,i])=>`<div class="metric"><div><span>${l}</span><strong>${n}</strong></div><span class="metric-icon">${i}</span></div>`).join('');
 const tabs=c?['Lookup','Hermes','Graph','Evidence','Activity','Reports','Ask the case','Monitors','Sources','Case','Trash','Free tools','Logins','Setup']:['Lookup','Overview','Sources','Trash','Free tools','Logins','Setup'];
 if(!tabs.includes(tab))tab=tabs[0];
 $('#tabs').className='tabs';$('#tabs').innerHTML=tabs.map(t=>`<button class="tab ${t===tab?'active':''}" data-tab="${t}">${t}</button>`).join('');
 $('#footStatus').textContent=(state.jobs||[]).some(j=>['running','queued'].includes(j.status))?'Collection in progress':'Saved locally';
 $('#metrics').style.display=tab==='Lookup'?'none':'grid';
 if(tab==='Lookup'){$('#caseTitle').textContent='One identifier. Multiple sources.';$('#eyebrow').textContent='STANDALONE LOOKUP';$('#caseDescription').textContent='Look up a phone, email, name, username, profile, domain, IP, or image. Keep every returned source field.';$('#runButton').hidden=true}
 Promise.resolve(({Lookup:lookup,Graph:graph,Evidence:evidence,Activity:activity,Reports:reports,'Ask the case':answers,Monitors:monitors,Sources:sources,Overview:overview,Hermes:hermes,Case:caseSettings,Trash:trash,Setup:readiness,'Free tools':freeTools,Logins:logins}[tab])()).catch(error=>toast(error.message));
}
function lookupOptions(){return `<div class="row"><div><label class="field" for="lookupPages">Pages per paginated source</label><input id="lookupPages" type="number" class="full" min="1" max="20" value="1"></div><div><label class="field" for="searchPage">Search results page</label><input id="searchPage" type="number" class="full" min="1" max="100" value="1"></div></div><div class="row"><div><label class="field" for="lookupLocation">Location context (optional)</label><input id="lookupLocation" class="full" placeholder="City, region, or country"></div><div><label class="field" for="lookupCompany">Company context (optional)</label><input id="lookupCompany" class="full" placeholder="Company or employer"></div></div><label class="field" style="font-weight:400"><input id="lookupPremium" type="checkbox"> Include OSINT Industries premium modules (additional provider charges)</label><label class="field" style="font-weight:400"><input id="lookupExact" type="checkbox"> Limit OSINT Industries name results to exact matches</label><label class="field" style="font-weight:400"><input id="lookupCaller" type="checkbox"> Include Twilio caller-name data where supported (additional charges)</label><p class="note">Pagination is a collection limit, not a masking filter. You can retrieve more pages when the source returns a continuation cursor. Name enrichment with People Data Labs requires a location or company.</p>${freeOptions()}`}
function readLookupOptions(){return {max_pages:Number($('#lookupPages').value),page:Number($('#searchPage').value),location:$('#lookupLocation').value.trim(),company:$('#lookupCompany').value.trim(),premium:$('#lookupPremium').checked,exact_match:$('#lookupExact').checked,caller_name:$('#lookupCaller').checked,...readFreeOptions()}}
function lookup(){ $('#content').innerHTML=`<div class="notice">${state.free_only?'Free mode is on: paid sources and AI calls are blocked. Local reports, search and exports still work.':'Choose free sources to avoid provider credits. Enable enforced free mode in Free tools.'} <button class="secondary" data-do="free-tools">Free tools</button></div><div class="split"><div class="panel" style="padding:25px"><h2>Run a standalone lookup</h2><div class="row"><div><label class="field" for="lookupType">Lookup type</label><select id="lookupType" class="full">${options(kinds,'phone')}</select></div><div><label class="field" for="lookupValue">Identifier or full name</label><input id="lookupValue" class="full" placeholder="+14155550123" autocomplete="off"></div></div>${lookupOptions()}${caseId?`<label class="field" style="font-weight:400"><input id="attachLookup" type="checkbox"> Add results to ${esc(state.case.title)}</label>`:''}<div class="dialog-actions"><button class="primary large" data-do="standalone-lookup">Run selected lookups</button></div></div><div><div class="panel" style="padding:25px"><div class="toolbar"><h2 style="margin:0">Choose sources</h2><span class="spacer"></span><button class="secondary" data-do="setup">Connect APIs</button></div><div id="lookupSources"></div></div><div class="notice" style="margin-top:17px">Atlas preserves returned fields without content-category masking. Relevance searches only change what is visible in a view. Provider-withheld values cannot be reconstructed. Authentication secrets remain protected.</div></div></div>`;lookupSourceList()}
function lookupSourceList(){const kind=$('#lookupType').value;const compatible=state.sources.filter(s=>s.implemented&&(s.types.includes('*')||s.types.includes(kind)));$('#lookupSources').innerHTML=compatible.map(s=>`<label class="lookup-source"><input type="checkbox" name="lookupSource" value="${s.id}" ${s.available?'':'disabled'} ${s.available&&(s.default_selected??!s.credential_env)?'checked':''}><span><strong>${esc(s.label)}</strong><small>${esc(s.coverage||'Returned source response')}</small>${badge(s.status)} ${s.free_eligible?badge('no provider credits'):badge('provider account')}${!s.available?`<small>Needs ${esc(s.credential_env||s.status)}</small>`:''}</span></label>`).join('')||'<p class="muted">No documented connector currently accepts this type.</p>';$('#lookupValue').placeholder=({phone:'+14155550123',email:'name@example.com',person:'Full name',username:'handle',domain:'example.com',ip:'8.8.8.8',image:'https://example.com/image.jpg'})[kind]||'Handle or full public profile URL'}
function overview(){ $('#content').innerHTML=`<div class="empty"><div class="empty-art"><span></span><span></span><span></span></div><h2>A clear view starts with a case.</h2><p>Create a case from a domain, email, username, or other identifier. Collect source responses, review extracted entities, and build a graph with a traceable evidence trail.</p><div class="welcome-actions"><button class="primary large" data-do="new-case">Create your first case</button><button class="secondary large" data-do="demo">Explore fictional demo</button></div></div><div class="card-grid"><div class="card"><div class="eyebrow">01 / COLLECT</div><h3 style="margin-top:17px">Sources you can inspect</h3><p>Keep timestamps, response hashes, and source material together. Import your saved WebVetted graph or evidence capture.</p></div><div class="card"><div class="eyebrow">02 / CONNECT</div><h3 style="margin-top:17px">A graph with provenance</h3><p>Review extracted entities before adding connections. A shared identifier is a lead, not proof of common identity.</p></div><div class="card"><div class="eyebrow">03 / EXPLAIN</div><h3 style="margin-top:17px">Reports backed by evidence</h3><p>Save report versions, follow evidence citations, and export a printable report or a structured case file.</p></div></div>` }
function toolbar(extra=''){return `<div class="toolbar"><input id="search" class="search" type="search" aria-label="Search this view" placeholder="Search ${tab.toLowerCase()}…" value="${esc(query)}">${extra}</div>`}
function filteredNodes(){return state.nodes.filter(n=>(!typeFilter||n.type===typeFilter)&&(!query||[n.label,n.identifier,n.type].some(v=>v.toLowerCase().includes(query.toLowerCase()))))}
const nodeColor=n=>n.review==='excluded'?'#b7bcb8':n.review==='disputed'?'#bb795d':n.depth===0?'#176b59':n.type==='email'?'#b29557':n.type==='ip'?'#7896a3':'#80a78c';
function graph(){
 const nodes=filteredNodes();if(!selected||!state.nodes.some(n=>n.id===selected))selected=nodes[0]?.id||null;
 $('#content').innerHTML=toolbar(`<select id="typeFilter" aria-label="Filter entity type"><option value="">All entity types</option>${options([...new Set(state.nodes.map(n=>n.type))].sort(),typeFilter)}</select><span class="spacer"></span><button class="secondary" data-do="add-node">＋ Add entity</button><button class="secondary" data-do="link">Link entities</button>`)+`<div class="graph-layout"><div class="panel"><div class="panel-title">Connection map <small>${nodes.length} of ${state.nodes.length} entities · drag to arrange</small></div><div class="graph-surface"><svg id="graph" aria-label="Interactive entity relationship graph" role="img"><g id="world"></g></svg><div class="graph-controls"><button data-do="zoom-out" aria-label="Zoom out">−</button><button data-do="zoom-in" aria-label="Zoom in">＋</button><button data-do="fit">Fit</button><button data-do="save-layout">Save layout</button><button data-do="reset-layout">Reset layout</button></div><span class="graph-legend">● Seed &nbsp; ● Observed entity</span></div></div><aside class="panel inspector" id="inspector"></aside></div><p class="note">Links describe relationships reported by a source. They do not establish that accounts belong to the same person. Drag the background to pan; scroll to zoom.</p>`;
 const svg=$('#graph'),w=svg.clientWidth||750,h=svg.clientHeight||465,initial=Object.keys(positions).length===0;
 const all=state.nodes,roots=all.filter(n=>n.depth===0),other=all.filter(n=>n.depth!==0);
 if(all.length>50){
   const columns=Math.ceil(Math.sqrt(Math.max(1,roots.length))),rootIds=new Set(roots.map(n=>n.id)),groups=new Map();
   roots.forEach((n,i)=>{positions[n.id]??=n.position||{x:400+(i%columns)*750,y:400+Math.floor(i/columns)*750}});
   other.forEach(n=>{const parent=state.edges.find(e=>e.to===n.id&&rootIds.has(e.from))?.from||roots[0]?.id;const group=groups.get(parent)||[];group.push(n);groups.set(parent,group)});
   for(const [parent,group] of groups){const center=positions[parent]||{x:400,y:400};group.forEach((n,i)=>{const r=65+Math.sqrt(i)*28,angle=i*2.399963;positions[n.id]??=n.position||{x:center.x+Math.cos(angle)*r,y:center.y+Math.sin(angle)*r}})}
 }else all.forEach(n=>{if(!positions[n.id]){const group=n.depth===0?roots:other,index=group.indexOf(n),angle=2*Math.PI*index/Math.max(1,group.length)-Math.PI/2;const radius=n.depth===0?(roots.length>1?95:0):Math.min(w*.37,180)+(index%3)*20;positions[n.id]=n.position||{x:w/2+Math.cos(angle)*radius,y:h/2+Math.sin(angle)*radius};}});
 if(initial&&state.case.viewport)view={...state.case.viewport};drawGraph();if(initial&&all.length>50&&!state.case.viewport)fit();bindGraph();inspector();
}
function drawGraph(){const nodes=filteredNodes(),ids=new Set(nodes.map(n=>n.id));const edges=state.edges.filter(e=>ids.has(e.from)&&ids.has(e.to));$('#world').setAttribute('transform',`translate(${view.x},${view.y}) scale(${view.k})`);$('#world').innerHTML=edges.map(e=>{const a=positions[e.from],b=positions[e.to];return `<line class="edge-line" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"><title>${esc(e.relationship)}${e.evidence_id?' · E'+e.evidence_id:''}</title></line>`}).join('')+nodes.map(n=>{const p=positions[n.id],r=n.depth===0?20:13;const label=n.label.length>25?n.label.slice(0,23)+'…':n.label,showLabel=nodes.length<70||view.k>.8||n.depth===0||selected===n.id;return `<g data-node="${n.id}" class="${selected===n.id?'node-selected':''}" transform="translate(${p.x},${p.y})" tabindex="0" role="button" aria-label="${esc(n.label)}"><circle class="node-shape" r="${r}" fill="${nodeColor(n)}"/><text text-anchor="middle" y="4" fill="white" font-size="12">${n.depth===0?'◇':'·'}</text>${showLabel?`<text class="node-label" text-anchor="middle" y="${r+17}">${esc(label)}</text>`:''}<title>${esc(n.type+': '+n.identifier)}</title></g>`}).join('')}
function bindGraph(){const svg=$('#graph');let drag=null;
 svg.onpointerdown=e=>{if(e.button!==0)return;const target=e.target.closest('[data-node]');drag={id:target?Number(target.dataset.node):null,x:e.clientX,y:e.clientY};if(drag.id){selected=drag.id;inspector();drawGraph()}svg.setPointerCapture(e.pointerId)};
 svg.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(drag.id){positions[drag.id].x+=dx/view.k;positions[drag.id].y+=dy/view.k}else{view.x+=dx;view.y+=dy}drawGraph()};
 svg.onpointerup=()=>drag=null;svg.onpointercancel=()=>drag=null;
 svg.onwheel=e=>{e.preventDefault();zoom(e.deltaY<0?1.12:.89,e.offsetX,e.offsetY)};
 svg.onkeydown=e=>{if(e.key==='Enter'&&e.target.dataset.node){selected=Number(e.target.dataset.node);inspector();drawGraph()}};
}
function zoom(f,x,y){const svg=$('#graph');x=x??svg.clientWidth/2;y=y??svg.clientHeight/2;const k=Math.min(5,Math.max(.08,view.k*f)),ratio=k/view.k;view.x=x-(x-view.x)*ratio;view.y=y-(y-view.y)*ratio;view.k=k;drawGraph()}
function fit(){const values=filteredNodes().map(n=>positions[n.id]);if(!values.length)return;const minX=Math.min(...values.map(p=>p.x))-70,maxX=Math.max(...values.map(p=>p.x))+70,minY=Math.min(...values.map(p=>p.y))-55,maxY=Math.max(...values.map(p=>p.y))+55;const svg=$('#graph');view.k=Math.min(1.7,svg.clientWidth/(maxX-minX),svg.clientHeight/(maxY-minY));view.x=(svg.clientWidth-(maxX+minX)*view.k)/2;view.y=(svg.clientHeight-(maxY+minY)*view.k)/2;drawGraph()}
function inspector(){const n=state.nodes.find(n=>n.id===selected);if(!n){$('#inspector').innerHTML='<h3>No entity selected</h3><p class="muted">Add a starting entity to begin.</p>';return}const evidence=state.evidence.filter(e=>e.node_id===n.id||state.edges.some(l=>l.to===n.id&&l.evidence_id===e.id));$('#inspector').innerHTML=`<div class="type-label">ENTITY DETAILS</div><div class="entity-icon">◇</div><h3>${esc(n.label)}</h3><span class="badge">${esc(n.type)}</span> ${badge(n.review)}<div class="divider"></div><label class="label" for="nodeReview">Review status</label><select id="nodeReview">${options(['unreviewed','supported','disputed','excluded'],n.review)}</select><label class="label" for="nodeNotes" style="margin-top:13px">Analyst notes</label><textarea id="nodeNotes" rows="3" placeholder="What supports this connection?">${esc(n.notes)}</textarea><button class="secondary" data-do="save-node">Save review</button><button class="primary" data-do="collect-selected">Collect from this entity</button><button class="secondary" data-do="edit-node">Edit entity</button><button class="secondary" data-do="add-related">Add related entity</button><button class="secondary" data-do="archive-record" data-table="nodes" data-id="${n.id}">Move entity to Trash</button><div class="divider"></div><div class="label">${evidence.length} linked evidence item${evidence.length===1?'':'s'}</div>${evidence.map(e=>`<button class="quiet" style="text-align:left" data-evidence="${e.id}">E${e.id} · ${esc(e.source)}</button>`).join('')}<details><summary>Connections for this entity</summary>${state.edges.filter(e=>e.from===n.id||e.to===n.id).map(e=>`<p>${esc(e.relationship)} · ${esc(state.nodes.find(other=>other.id===(e.from===n.id?e.to:e.from))?.label||'')}<button class="quiet" data-do="archive-record" data-table="edges" data-id="${e.id}">Remove connection</button></p>`).join('')||'<p>No connections.</p>'}</details><p class="note">Origin: ${esc(n.origin||'unknown')} · expansion depth ${n.depth}</p>`}
async function evidence(){const searchQuery=query,currentCase=caseId;let rows=state.evidence;if(searchQuery){const response=await fetch(`/api/evidence-search?case=${currentCase}&q=${encodeURIComponent(searchQuery)}`);const data=await response.json();if(tab!=='Evidence'||query!==searchQuery||caseId!==currentCase)return;if(!response.ok){toast(data.error);return}const ids=new Set(data.results.map(r=>r.id));rows=rows.filter(e=>ids.has(e.id))}$('#content').innerHTML=toolbar(`<button class="secondary" data-do="compare-evidence" ${state.evidence.length?'':'disabled'}>Compare evidence</button><button class="secondary" data-do="manual-evidence" ${state.nodes.length?'':'disabled'}>Add source evidence</button><span class="coverage">${rows.length} of ${state.evidence.length} records · searches every stored field</span>`)+(rows.length?`<div class="evidence-list">${rows.map(e=>`<article class="card"><div class="card-top"><small class="mono">E${e.id}</small>${badge(e.review)}</div><h3>${esc(e.source)}</h3><small>${date(e.timestamp)} · ${e.entities.length} extracted entities</small><div class="toolbar" style="margin-top:12px"><button class="primary" data-evidence="${e.id}">Read complete evidence ↗</button><a class="secondary" href="/api/source-response?case=${caseId}&id=${e.id}" download>Download full response</a></div><details><summary>Collection notes / source description</summary><p class="full-description">${esc(e.snippet||'No source description provided.')}</p></details></article>`).join('')}</div>`:'<div class="empty"><h2>No evidence matches.</h2><p>Search checks all stored fields, including fields outside summaries and extracted leads.</p></div>')}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}catch{return ''}}
async function showEvidence(id){const response=await fetch(`/api/evidence?case=${caseId}&id=${id}`),e=await response.json();if(!response.ok)throw Error(e.error);const pending=e.entities.filter(a=>!e.applied_keys.includes(a.entity_key));const fields=returnedFields(e.raw);modal(`Complete evidence E${e.id}`,`<div class="notice">${esc(e.source)} · ${date(e.timestamp)}${e.origin==='import'?' · Imported historical record':''}</div><p>All ${fields.length} returned field values are shown below. Contact details are not masked. Authentication secrets are protected; any provider masking remains exactly as received.</p><div class="toolbar"><a class="secondary" href="/api/source-response?case=${caseId}&id=${e.id}" download="atlas-evidence-${e.id}.json">Download full response</a>${safeLink(e.url)}<button class="secondary" data-do="evidence-history" data-id="${e.id}">Source history / compare</button>${e.collection?.next_cursor?`<label for="morePages">Additional pages</label><input id="morePages" type="number" min="1" max="20" value="1" style="width:75px"><button class="primary" data-do="continue-source" data-id="${e.id}">Retrieve more pages</button>`:''}</div><h3>Complete returned details</h3><div class="source-fields"><table><thead><tr><th>Field path</th><th>Complete value</th></tr></thead><tbody>${fields.map(([path,value])=>`<tr><td class="mono">${esc(path)}</td><td class="field-value">${esc(value)}</td></tr>`).join('')}</tbody></table></div><details style="margin-top:18px"><summary>Original response structure</summary><pre>${esc(JSON.stringify(e.raw,null,2))}</pre></details><details><summary>Collection notes / source description</summary><p class="full-description">${esc(e.snippet)}</p></details>${e.collection&&Object.keys(e.collection).length?`<details open><summary>Collection coverage and remaining pages</summary><pre>${esc(JSON.stringify(e.collection,null,2))}</pre></details>`:''}<p class="mono">SHA-256: ${esc(e.sha256)}</p><p class="note">Hash covers the stored response after authentication-secret protection; it does not authenticate the source.${e.no_match?' The source reported no match.':''}</p><div class="divider"></div><label class="field" for="eReview">Review status</label><select id="eReview">${options(['unreviewed','supported','disputed','excluded'],e.review)}</select><label class="field" for="eNotes">Analyst notes</label><textarea id="eNotes" class="full" rows="2">${esc(e.notes)}</textarea><button class="secondary" data-do="save-evidence" data-id="${e.id}" style="margin-top:10px">Save review</button><div class="divider"></div><h3>Extracted entities · ${e.entities.length}</h3><p class="muted">${e.entities.length-pending.length} already applied. Select additional leads to add to the graph.</p>${pending.length?`<div class="checks">${pending.map(a=>`<label><input type="checkbox" name="entityKey" value="${esc(a.entity_key)}" checked><span>${esc(a.label)} <small>· ${esc(a.type)} · ${esc(a.relationship)}</small></span></label>`).join('')}</div><button class="primary" data-do="apply" data-id="${e.id}" style="margin-top:12px">Add selected to graph</button>`:'<p class="muted">No unapplied extracted entities.</p>'}<button class="secondary" data-do="extract" data-id="${e.id}" style="margin:12px 0 0 8px">Re-extract known fields</button><details><summary>Complete stored record, including all extracted entities and import metadata</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details>`)}
function comparisonChooser(afterId){
 const after=state.evidence.find(e=>e.id===afterId)||state.evidence.at(-1);if(!after)return;
 const history=state.evidence.filter(e=>e.node_id===after.node_id&&e.transform_id===after.transform_id);
 const earlier=history.filter(e=>e.id<after.id).at(-1),before=earlier||history.find(e=>e.id!==after.id)||after;
 const choices=id=>state.evidence.map(e=>`<option value="${e.id}" ${e.id===id?'selected':''}>E${e.id} · ${esc(e.source)} · ${esc(state.nodes.find(n=>n.id===e.node_id)?.label||'Unknown entity')} · ${date(e.timestamp)}</option>`).join('');
 modal('Compare source responses',`<p>Compare complete returned fields. Existing evidence is never changed. The suggested pair uses the same entity and transform when a prior response exists.</p><div class="row"><div><label class="field" for="compareBefore">Before</label><select id="compareBefore" class="full">${choices(before.id)}</select></div><div><label class="field" for="compareAfter">After</label><select id="compareAfter" class="full">${choices(after.id)}</select></div></div><div class="dialog-actions"><button class="primary" data-do="run-comparison">Show field changes</button></div><h3>Source history · ${history.length} records</h3><p class="note">Same entity and transform. Different request settings or pages may return different coverage.</p><div class="stack">${[...history].reverse().map(e=>`<div><button class="quiet" data-evidence="${e.id}">E${e.id} · ${date(e.timestamp)}</button> ${badge(e.review)} ${e.origin==='import'?'Imported record':''}</div>`).join('')}</div>`);
}
async function showComparison(before,after){
 const currentCase=caseId,url=`/api/evidence-compare?case=${currentCase}&before=${before}&after=${after}`;
 const response=await fetch(url),data=await response.json();if(!response.ok)throw Error(data.error);if(caseId!==currentCase)return;
 const value=(row,key)=>Object.hasOwn(row,key)?`<pre>${esc(JSON.stringify(row[key],null,2))}</pre>`:'<em>Field absent</em>';
 modal(`Evidence comparison · E${before} → E${after}`,`<div class="toolbar"><button class="secondary" data-evidence="${before}">Open before · E${before}</button><button class="secondary" data-evidence="${after}">Open after · E${after}</button><a class="secondary" href="${url}&download=1" download>Download comparison JSON</a><button class="secondary" data-do="compare-evidence" data-id="${after}">Choose another pair</button></div><p>${data.counts.added} added · ${data.counts.removed} removed · ${data.counts.changed} changed · ${data.unchanged_fields} unchanged values</p>${!data.same_source_entity?'<div class="notice">These records use different entities or transforms. Differences do not establish a change in the same source.</div>':''}${!data.same_request_options?'<div class="notice">Request settings differ. Changes may reflect different pages or search options.</div>':''}<p class="note">All differences are shown with complete values. Arrays are compared by position, so reordering can appear as changes. Source timestamps and metadata are included. Values describe the stored, authentication-protected responses; a missing field does not prove a real-world deletion.</p>${data.changes.length?`<div class="source-fields comparison-fields"><table><thead><tr><th>Field / change</th><th>Before</th><th>After</th></tr></thead><tbody>${data.changes.map(row=>`<tr><td class="mono">${esc(row.path)}<br>${badge(row.kind)}</td><td>${value(row,'before')}</td><td>${value(row,'after')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">No returned fields changed. The complete responses remain available above.</div>'}<details><summary>Source records, hashes, request settings, and collection coverage</summary><pre>${esc(JSON.stringify({before:data.before,after:data.after},null,2))}</pre></details>`);
}
function returnedFields(value,path='$'){if(value&&typeof value==='object'){const entries=Object.entries(value);if(entries.length)return entries.flatMap(([key,item])=>returnedFields(item,path+(Array.isArray(value)?`[${key}]`:`[${JSON.stringify(key)}]`)))}return [[path,typeof value==='string'?value:JSON.stringify(value)]]}
function sourceChoices(nodeIds){const types=state.nodes.filter(n=>nodeIds.includes(n.id)).map(n=>n.type);return state.sources.filter(s=>s.available&&(s.types.includes('*')||s.types.some(t=>types.includes(t))))}
function collect(nodeIds){nodeIds=nodeIds||state.nodes.filter(n=>n.depth===0&&n.review!=='excluded').map(n=>n.id);const ready=sourceChoices(nodeIds);modal('Collect evidence',`<p class="muted">Run connected sources against ${nodeIds.length} selected seed${nodeIds.length===1?'':'s'}. Provider charges follow your accounts; the limit below counts connector runs, not money.</p><input id="runNodes" type="hidden" value="${nodeIds.join(',')}"><div class="checks">${ready.map(s=>`<label><input type="checkbox" name="transform" value="${s.id}" ${(s.default_selected??!s.credential_env)?'checked':''}><span>${esc(s.label)} ${s.credential_env?'<small>· uses your provider account</small>':''}</span></label>`).join('')||'<p class="muted">No connected source accepts these entities. See Sources for available connectors.</p>'}</div><div class="row"><div><label class="field" for="maxRuns">Maximum connector runs</label><input id="maxRuns" class="full" type="number" min="1" max="30" value="5"></div><div><label class="field" for="maxDepth">Expansion levels after seeds</label><select id="maxDepth" class="full"><option value="0">0 — seeds only</option><option value="1">1 — graph expansion</option><option value="2">2 — deeper expansion</option></select></div></div>${lookupOptions()}<label class="field" style="font-weight:400"><input id="autoApply" type="checkbox"> Automatically apply extracted leads and expand them</label><p class="note">Default: review leads before applying. Cancellation stops further work after the current request finishes. AI web searches may make multiple billed tool calls.</p><div class="dialog-actions"><button class="primary" data-do="start-job" ${ready.length?'':'disabled'}>Start collection</button></div>`)}
function activity(){const jobs=[...state.jobs].reverse();$('#content').innerHTML=`<div class="split"><div><h2>Investigation runs</h2><div class="stack">${jobs.map(j=>`<div class="card"><div class="card-top"><strong>Run ${j.id}</strong>${badge(j.status)}</div><h3>${esc(j.phase.replaceAll('_',' '))}</h3><p>${esc(j.message)}</p><small>${j.completed_runs+j.failed_runs} / ${j.max_runs} connector runs · ${date(j.created_at)}</small>${['queued','running'].includes(j.status)?`<br><button class="secondary" data-do="cancel-job" data-id="${j.id}">Stop after current request</button>`:''}</div>`).join('')||'<div class="card"><p>No collection jobs yet.</p></div>'}</div><h2 style="margin-top:24px">Source outcomes</h2><div class="table-wrap"><table><thead><tr><th>Transform</th><th>Status</th><th></th></tr></thead><tbody>${[...state.runs].reverse().map(r=>`<tr><td>${esc(r.transform_id)}<br><small class="muted">${esc(r.message||'')}</small></td><td>${badge(r.status)}</td><td>${r.evidence_id?`<button class="quiet" data-evidence="${r.evidence_id}">E${r.evidence_id}</button>`:''}<button class="quiet" data-do="inspect-run" data-id="${r.id}">Details</button>${['failed','interrupted','partial'].includes(r.status)?`<button class="secondary" data-do="retry" data-id="${r.id}" ${connectable(r.transform_id)?'':'disabled'}>Retry</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><div class="panel-title">Activity trail <small>${state.events.length} events</small></div><div class="timeline">${[...state.events].reverse().map(e=>`<div class="event">${esc(e.message)} ${e.evidence_id?`<button class="evidence-link" data-evidence="${e.evidence_id}">E${e.evidence_id}</button>`:''}${e.previous_evidence_id?`<button class="secondary" data-do="compare-pair" data-before="${e.previous_evidence_id}" data-after="${e.evidence_id}">Compare changes</button>`:''}<small>${date(e.created_at)}</small></div>`).join('')}</div></div></div>`}
function connectable(id){return state.sources.some(s=>s.id===id&&s.available)}
function citations(text){return esc(text).replace(/\[E(\d+)\]/g,(match,id)=>state.evidence.some(e=>e.id===Number(id))?`<button class="evidence-link" data-evidence="${id}">[E${id}]</button>`:match)}
function reports(){const latest=state.reports.at(-1);$('#content').innerHTML=`<div class="toolbar"><button class="primary" data-do="report">Generate complete evidence report</button><button class="secondary" data-do="ai-report" ${state.ai_ready?'':'disabled'}>Add AI interpretation</button><span class="spacer"></span><button class="secondary" data-do="export">↓ Export complete case JSON</button></div><p class="note">New reports include complete stored evidence, graph records, and collection outcomes. Explicit analyst exclusions are listed. AI receives complete eligible evidence or stops before sending if it exceeds the configured ${Number(state.ai_context_limit).toLocaleString()}-character input limit. No excerpts are substituted.</p>${state.reports.length?`<div class="toolbar"><select id="reportVersion" aria-label="Report version">${[...state.reports].reverse().map(r=>`<option value="${r.id}">Version ${r.version} · ${date(r.created_at)} · ${r.format==='complete-evidence-v2'?'complete records':'legacy summary'}${r.ai?' · AI-assisted':''}</option>`).join('')}</select><button class="secondary" id="printReport" data-do="print" data-id="${latest.id}">Print / save PDF ↗</button></div><div class="panel report-text" id="reportText">Loading complete report…</div>`:'<div class="empty"><h2>Every detail, with its source.</h2><p>Generate an immutable report with complete stored source records and an evidence trail.</p></div>'}`;if(latest)loadReport(latest.id).catch(error=>toast(error.message))}
async function loadReport(id){const currentCase=caseId,response=await fetch(`/api/report?case=${currentCase}&id=${id}&format=json`),r=await response.json();if(tab!=='Reports'||caseId!==currentCase||Number($('#reportVersion')?.value)!==id)return;if(!response.ok){toast(r.error);return}$('#reportText').innerHTML=citations(r.text);$('#printReport').dataset.id=r.id}
function answers(){$('#content').innerHTML=`<div class="panel" style="padding:24px"><h2>Ask the case</h2><p class="muted">Search every field in the complete stored evidence, including source responses and analyst notes. All matches are returned. Optional AI receives complete eligible records or stops if the configured input limit is exceeded.</p><label class="label" for="question">Question or search terms</label><textarea id="question" class="full" rows="2" placeholder="What evidence supports this connection?"></textarea><div class="toolbar" style="margin-top:14px"><button class="primary" data-do="question">Search evidence</button><button class="secondary" data-do="ai-question" ${state.ai_ready?'':'disabled'}>Ask with AI</button><span class="note">AI uses your configured account.</span></div></div><div class="stack" style="margin-top:18px">${[...state.answers].reverse().map(a=>`<div class="card"><div class="card-top"><h3>${esc(a.question)}</h3>${badge(a.ai?'AI-assisted':'evidence search')}</div><div class="answer">${citations(a.answer)}</div><p class="note">${date(a.created_at)}</p><button class="quiet" data-do="archive-record" data-table="answers" data-id="${a.id}">Move answer to Trash</button></div>`).join('')}</div>`}
function monitors(){$('#content').innerHTML=`<div class="toolbar"><button class="primary" data-do="new-monitor">＋ Monitor a source</button></div><div class="notice">Monitors refresh a source while this app is running. Changed response hashes appear in Activity. A changed hash can reflect a timestamp or metadata change; review the actual evidence. Provider account charges still apply.</div><div class="table-wrap"><table><thead><tr><th>Entity / source</th><th>Interval</th><th>Last checked</th><th>Status</th><th></th></tr></thead><tbody>${state.monitors.map(m=>`<tr><td>${esc(state.nodes.find(n=>n.id===m.node_id)?.label)}<br><small>${esc(m.transform_id)}</small></td><td>${m.interval_seconds/3600} hours</td><td>${date(m.last_checked)}${m.last_evidence_id?`<br><button class="quiet" data-evidence="${m.last_evidence_id}">Latest evidence · E${m.last_evidence_id}</button>`:''}${m.previous_evidence_id&&m.last_change_evidence_id?`<br><button class="secondary" data-do="compare-pair" data-before="${m.previous_evidence_id}" data-after="${m.last_change_evidence_id}">Compare last change</button>`:''}</td><td>${badge(m.enabled?'enabled':'paused')}</td><td><button class="secondary" data-do="toggle-monitor" data-id="${m.id}">${m.enabled?'Pause':'Resume'}</button><button class="quiet" data-do="edit-monitor" data-id="${m.id}">Edit interval</button><button class="quiet" data-do="archive-record" data-table="monitors" data-id="${m.id}">Remove</button></td></tr>`).join('')||'<tr><td colspan="5">No source monitors configured.</td></tr>'}</tbody></table></div>`}
function sources(){const rows=state.sources.filter(s=>[s.label,s.id,...s.types].some(v=>v.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>Number(b.available)-Number(a.available)||Number(b.implemented)-Number(a.implemented)||a.label.localeCompare(b.label));$('#content').innerHTML=`<div class="notice">${state.sources.filter(s=>s.implemented).length} connector implementations · ${state.sources.filter(s=>s.available).length} currently connected. The reference catalog contains 73 captured transform IDs. A catalog entry alone is not a working integration.</div>${toolbar('<button class="secondary" data-do="setup">Connection setup</button>')}<div class="table-wrap"><table><thead><tr><th>Source / transform</th><th>Entity types</th><th>Connection</th><th>Reference credits*</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.label)}</strong><br><small class="mono muted">${esc(s.id)}</small>${s.coverage?`<br><small>${esc(s.coverage)}</small>`:''}</td><td>${esc(s.types.join(', '))}</td><td>${badge(s.status)}${s.credential_env?`<br><span class="note">${esc(s.credential_env)}</span>`:''}</td><td>${s.reference_cost??'—'}</td></tr>`).join('')}</tbody></table></div><p class="note">*Credits are historical labels from the captured WebVetted configuration. They are not Atlas prices or a prediction of your provider charges. Built connectors can have different coverage from the reference feature. Paid adapters need live validation with your own account.</p>`}
async function readiness(){
 const response=await fetch('/api/readiness'),r=await response.json();if(!response.ok)throw Error(r.error);if(tab!=='Setup')return;
 $('#content').innerHTML=`<div class="toolbar"><button class="primary" data-do="setup">Enter / update API keys</button><button class="secondary" data-do="walkthrough">Getting started</button><a class="secondary" href="/api/backup" download>Download workspace backup</a></div><div class="card-grid"><div class="card"><h3>${r.configured_sources} sources configured</h3><p>${r.implemented_sources} adapters implemented. Missing keys and account entitlements are distinct from missing integrations.</p></div><div class="card"><h3>${r.checks.database&&r.checks.static_files?'Local checks passed':'A local check needs attention'}</h3><p>Database integrity: ${r.checks.database?'OK':'needs attention'}<br>App files: ${r.checks.static_files?'OK':'missing'}<br>Hermes bridge: ${r.checks.hermes_bridge?'installed locally':'missing'}</p></div><div class="card"><h3>${r.active_jobs} active jobs</h3><p>Saved credentials: ${r.keys.fields.filter(f=>f.saved).length}<br>Windows encrypted storage: ${r.keys.persistent_storage_available?'available':'use environment or session settings'}</p></div></div>${r.keys.storage_error?`<div class="notice">${esc(r.keys.storage_error)}</div>`:''}<h2>Source readiness</h2><p>Setup checks make no provider calls. A successful stored run is historical evidence, not a guarantee that your current key or plan still works. Verify connected sources with a lookup on an identifier you choose.</p><div class="table-wrap"><table><thead><tr><th>Source</th><th>Connection</th><th>Latest stored result</th></tr></thead><tbody>${r.sources.filter(s=>s.implemented).map(s=>`<tr><td>${esc(s.label)}</td><td>${badge(s.status)}</td><td>${s.last_outcome?`${badge(s.last_outcome.status)} · ${date(s.last_outcome.completed_at)}<br>${esc(s.last_outcome.message||'')}`:'Not yet tested with a recorded run'}</td></tr>`).join('')}</tbody></table></div><p class="note">Workspace backups contain the complete local case database, including report history, plans and Trash. API keys are excluded. Restore-Atlas.ps1 restores to a new folder and pauses schedules to avoid replaying charged requests.</p>`;
}
function walkthrough(){modal('From keys to a complete investigation',`<ol class="guide-steps"><li><strong>Connect your sources.</strong> Enter keys in Setup. Windows can remember them encrypted for your account.</li><li><strong>Run a first lookup.</strong> Choose phone, email, name, username, profile, domain, IP or image URL. Select the sources you want; connected paid sources use your provider account.</li><li><strong>Read the complete evidence.</strong> Every returned field is available. Apply selected extracted leads to the graph after review.</li><li><strong>Prepare deeper collection.</strong> Open Hermes to create a plan, inspect sources and limits, then start. This works without installing Hermes itself.</li><li><strong>Compare and explain.</strong> Compare source history, search full fields, save reports, and schedule refreshes when useful.</li><li><strong>Back up your work.</strong> Use Setup to download a complete workspace backup. Credentials are stored separately.</li></ol><p class="note">Hermes integration is prepared for later. Your existing BT/default, Ronin/researcher and Legion/ops roles are not installed or modified by Atlas.</p><button class="primary" data-do="setup">Connect sources</button>`)}

