 walkthrough,
 'refresh-logins':()=>refresh(),
 'save-settings':async()=>{const values=Object.fromEntries([...document.querySelectorAll('[data-setting]')].filter(i=>i.value.trim()).map(i=>[i.dataset.setting,i.value]));const remove=[...document.querySelectorAll('[data-remove-setting]:checked')].map(i=>i.dataset.removeSetting);if(remove.some(k=>values[k]))throw Error('Choose either a new value or removal for each setting.');await api('settings',{values,remove,persist:$('#persistSettings').checked});document.querySelectorAll('[data-setting]').forEach(i=>i.value='');close();await refresh();toast('Connections updated. No provider requests were made.')},
